import sys

def find_permutation(N, A):
    # Initialize the permutation with -1
    P = [-1] * N

    # Stack to keep track of indices
    stack = []

    # Fill the permutation
    for i in range(N):
        if A[i] == -1:
            # If A[i] is -1, we can place the smallest available number
            P[i] = N - len(stack)
        else:
            # Find the position for P[i]
