                P[i] = stack[-1][1] + 1
            else:
                P[i] = 1

        # Push the current index onto the stack
        stack.append((A[i], i))

    # Check if the permutation is valid
    for i in range(N):
        if A[i] != -1:
            max_j = 0
            for j in range(i):
                if P[j] > P[i]:
                    max_j = max(max_j, j + 1)
